when.set-body:
@{
            var r = context.Response.Body.As();
            var facets = (JObject)r["@search.facets"];
            var result = new JObject(
                new JProperty("index", "__INDEX_NAME__"),
                new JProperty("totalChunks", r["@odata.count"]));
            foreach (var f in facets.Properties()) {
                var o = new JObject();
                foreach (var v in (JArray)f.Value) { o.Add(new JProperty((string)v["value"], v["count"])); }
                result.Add(new JProperty(f.Name == "article_id" ? "chunksPerArticle" : f.Name, o));
            }
            return result.ToString();
        }
